"""Offline synthetic QUIC v1 trace auditor.

Reads one JSON document from stdin and writes one JSON document to stdout.
Invalid input produces {"error":"INVALID_INPUT"}.
"""
import sys
import json
import re
import bisect

MAX_OFF = 4611686018427387903  # 2**62 - 1
MAX_T = 1000000000000
MAX_IDLE = 1000000000
MAX_REQUEST = 16 * 1024 * 1024
MAX_FRAME_DATA = 2 * 1024 * 1024
MAX_RANGE_PAIRS = 32


class InvalidInput(Exception):
    pass


class ProtoError(Exception):
    __slots__ = ("code", "frame")

    def __init__(self, code, frame):
        self.code = code
        self.frame = frame


def _reject_constant(_s):
    raise InvalidInput()


def _reject_float(_s):
    raise InvalidInput()


def _no_duplicate_pairs(pairs):
    d = {}
    for k, v in pairs:
        if k in d:
            raise InvalidInput()
        d[k] = v
    return d


_HEX_RE = re.compile(r"[0-9a-f]*\Z")


def _is_int(v):
    return type(v) is int


def _is_bool(v):
    return type(v) is bool


def _need_dict(v, keys):
    if type(v) is not dict:
        raise InvalidInput()
    if len(v) != len(keys):
        raise InvalidInput()
    for k in keys:
        if k not in v:
            raise InvalidInput()
    return v


def _hex_len(s):
    if type(s) is not str:
        raise InvalidInput()
    n = len(s)
    if n > 4096 or (n & 1):
        raise InvalidInput()
    if _HEX_RE.fullmatch(s) is None:
        raise InvalidInput()
    return n // 2


def _int_domain(v, lo, hi):
    if not _is_int(v) or v < lo or v > hi:
        raise InvalidInput()
    return v


def _validate_ranges(v, config):
    """Structural validation.  Returns decoded pairs (list of tuples)."""
    if type(v) is not list:
        raise InvalidInput()
    if len(v) > MAX_RANGE_PAIRS:
        raise InvalidInput()
    out = []
    prev_low = None
    prev_high = None
    for pair in v:
        if type(pair) is not list or len(pair) != 2:
            raise InvalidInput()
        lo = pair[0]
        hi = pair[1]
        if not _is_int(lo) or not _is_int(hi):
            raise InvalidInput()
        if lo < 0 or lo > MAX_OFF or hi < 0 or hi > MAX_OFF:
            raise InvalidInput()
        if config:
            if lo > hi:
                raise InvalidInput()
            if prev_low is not None:
                # must ascend by low, be disjoint and nonadjacent
                if lo <= prev_high + 1:
                    raise InvalidInput()
            prev_low = lo
            prev_high = hi
        out.append((lo, hi))
    return out


FRAME_KEYS = {
    "PADDING": frozenset(("type",)),
    "PING": frozenset(("type",)),
    "ACK": frozenset(("type", "ranges")),
    "CRYPTO": frozenset(("type", "offset", "data_hex")),
    "STREAM": frozenset(("type", "id", "offset", "data_hex", "fin")),
    "RESET_STREAM": frozenset(("type", "id", "final_size")),
    "STOP_SENDING": frozenset(("type", "id")),
    "CLOSE": frozenset(("type", "app", "code")),
    "HANDSHAKE_DONE": frozenset(("type",)),
    "UNKNOWN": frozenset(("type",)),
}


def _validate_frame(fr):
    if type(fr) is not dict:
        raise InvalidInput()
    typ = fr.get("type")
    if type(typ) is not str or typ not in FRAME_KEYS:
        raise InvalidInput()
    keys = FRAME_KEYS[typ]
    if len(fr) != len(keys):
        raise InvalidInput()
    for k in keys:
        if k not in fr:
            raise InvalidInput()
    if typ == "PADDING" or typ == "PING" or typ == "HANDSHAKE_DONE" or typ == "UNKNOWN":
        return 0
    if typ == "ACK":
        _validate_ranges(fr["ranges"], False)
        return 0
    if typ == "CRYPTO":
        _int_domain(fr["offset"], 0, MAX_OFF)
        return _hex_len(fr["data_hex"])
    if typ == "STREAM":
        _int_domain(fr["id"], 0, MAX_OFF)
        _int_domain(fr["offset"], 0, MAX_OFF)
        if not _is_bool(fr["fin"]):
            raise InvalidInput()
        return _hex_len(fr["data_hex"])
    if typ == "RESET_STREAM":
        _int_domain(fr["id"], 0, MAX_OFF)
        _int_domain(fr["final_size"], 0, MAX_OFF)
        return 0
    if typ == "STOP_SENDING":
        _int_domain(fr["id"], 0, MAX_OFF)
        return 0
    if typ == "CLOSE":
        if not _is_bool(fr["app"]):
            raise InvalidInput()
        _int_domain(fr["code"], 0, MAX_OFF)
        return 0
    raise InvalidInput()


def _validate_config(cfg):
    _need_dict(cfg, ("early", "overlap", "buffer_packets", "idle_ms",
                     "max_streams_bidi", "max_streams_uni", "max_stream_data",
                     "max_data", "crypto_limit", "sent"))
    if not _is_bool(cfg["early"]):
        raise InvalidInput()
    if cfg["overlap"] not in ("reject", "first"):
        raise InvalidInput()
    if type(cfg["overlap"]) is not str:
        raise InvalidInput()
    _int_domain(cfg["buffer_packets"], 0, 1024)
    _int_domain(cfg["idle_ms"], 0, MAX_IDLE)
    _int_domain(cfg["max_streams_bidi"], 0, 1024)
    _int_domain(cfg["max_streams_uni"], 0, 1024)
    _int_domain(cfg["max_stream_data"], 0, 65536)
    _int_domain(cfg["max_data"], 0, MAX_OFF)
    _int_domain(cfg["crypto_limit"], 0, 65536)
    sent = _need_dict(cfg["sent"], ("I", "H", "A"))
    for lvl in ("I", "H", "A"):
        _validate_ranges(sent[lvl], True)


EVENT_KEYS = {
    "key": frozenset(("t", "op", "level", "action")),
    "tick": frozenset(("t", "op")),
    "datagram": frozenset(("t", "op", "bytes", "packets")),
}

LEVELS = ("I", "H", "Z", "A")
_ID_RE = re.compile(r"[A-Za-z0-9_-]{1,32}\Z")


def _validate_root(obj):
    _need_dict(obj, ("version", "traces"))
    if not _is_int(obj["version"]) or obj["version"] != 1:
        raise InvalidInput()
    traces = obj["traces"]
    if type(traces) is not list:
        raise InvalidInput()
    if len(traces) > 32:
        raise InvalidInput()
    seen_ids = set()
    total_events = 0
    total_packets = 0
    total_frames = 0
    total_data = 0
    for tr in traces:
        _need_dict(tr, ("id", "config", "events"))
        tid = tr["id"]
        if type(tid) is not str or _ID_RE.fullmatch(tid) is None:
            raise InvalidInput()
        if tid in seen_ids:
            raise InvalidInput()
        seen_ids.add(tid)
        _validate_config(tr["config"])
        events = tr["events"]
        if type(events) is not list:
            raise InvalidInput()
        total_events += len(events)
        if total_events > 20000:
            raise InvalidInput()
        prev_t = -1
        for ev in events:
            if type(ev) is not dict:
                raise InvalidInput()
            op = ev.get("op")
            if type(op) is not str or op not in EVENT_KEYS:
                raise InvalidInput()
            keys = EVENT_KEYS[op]
            if len(ev) != len(keys):
                raise InvalidInput()
            for k in keys:
                if k not in ev:
                    raise InvalidInput()
            t = _int_domain(ev["t"], 0, MAX_T)
            if t < prev_t:
                raise InvalidInput()
            prev_t = t
            if op == "key":
                if ev["level"] not in LEVELS:
                    raise InvalidInput()
                if type(ev["level"]) is not str:
                    raise InvalidInput()
                if ev["action"] not in ("install", "discard"):
                    raise InvalidInput()
                if type(ev["action"]) is not str:
                    raise InvalidInput()
            elif op == "tick":
                pass
            else:
                _int_domain(ev["bytes"], 0, 65535)
                packets = ev["packets"]
                if type(packets) is not list:
                    raise InvalidInput()
                if len(packets) < 1 or len(packets) > 16:
                    raise InvalidInput()
                total_packets += len(packets)
                if total_packets > 20000:
                    raise InvalidInput()
                for pkt in packets:
                    _need_dict(pkt, ("level", "pn", "auth", "frames"))
                    if pkt["level"] not in LEVELS:
                        raise InvalidInput()
                    if type(pkt["level"]) is not str:
                        raise InvalidInput()
                    _int_domain(pkt["pn"], 0, MAX_OFF)
                    if not _is_bool(pkt["auth"]):
                        raise InvalidInput()
                    frames = pkt["frames"]
                    if type(frames) is not list:
                        raise InvalidInput()
                    if len(frames) > 64:
                        raise InvalidInput()
                    total_frames += len(frames)
                    if total_frames > 60000:
                        raise InvalidInput()
                    for fr in frames:
                        total_data += _validate_frame(fr)
                        if total_data > MAX_FRAME_DATA:
                            raise InvalidInput()
    return obj


def _parse(raw):
    if len(raw) > MAX_REQUEST:
        raise InvalidInput()
    try:
        text = raw.decode("utf-8")
    except Exception:
        raise InvalidInput()
    try:
        obj = json.loads(
            text,
            object_pairs_hook=_no_duplicate_pairs,
            parse_constant=_reject_constant,
            parse_float=_reject_float,
        )
    except InvalidInput:
        raise
    except Exception:
        raise InvalidInput()
    return obj


# ---------------------------------------------------------------------------
# Replay


_MISSING = object()


class TraceRunner:
    __slots__ = (
        "cfg", "early", "overlap", "buffer_packets", "idle_ms",
        "max_streams_bidi", "max_streams_uni", "max_stream_data",
        "max_data", "crypto_limit", "sent", "sent_lows",
        "keys", "state", "code", "at_ms", "source", "peer_code",
        "last_activity", "pending", "pnsets", "streams", "tot", "crypto",
        "results",
    )

    def __init__(self, trace):
        cfg = trace["config"]
        self.cfg = cfg
        self.early = cfg["early"]
        self.overlap = cfg["overlap"]
        self.buffer_packets = cfg["buffer_packets"]
        self.idle_ms = cfg["idle_ms"]
